<script setup lang="ts">
import { computed, onMounted, onUnmounted, reactive, ref } from 'vue'
import Icon from './Icon.vue'
import InputStatistics from './InputStatistics.vue'
import LiveInputFailover from './LiveInputFailover.vue'
import BilibiliConnection from './BilibiliConnection.vue'
import type { AppState, Command, CommandResult, LiveInputInfo } from '../../../packages/shared/src'
const props=defineProps<{state:AppState;execute:(command:Command,message?:string)=>Promise<CommandResult|undefined>}>()
const devices=ref<MediaDeviceInfo[]>([])
const edit=reactive(JSON.parse(JSON.stringify(props.state.config)))
const input=ref<LiveInputInfo>()
const runtime=ref<{dataDirectory?:string;localTest?:boolean;driverInstalled?:boolean;platform?:string}>()
const showToken=ref(false)
const isDesktop=!!window.shop
if(!['douyin','bilibili'].includes(edit.input.platform))edit.input.platform='douyin'
let timer:ReturnType<typeof setInterval>|undefined
const stream= computed(()=>devices.value.find(d=>d.deviceId===props.state.config.audio.streamDeviceId))
const windows=computed(()=>runtime.value?.platform==='win32'||/Windows/i.test(navigator.userAgent))
const virtualName=computed(()=>windows.value?'CABLE Input / 扬声器 (VB-Audio)':'BlackHole 2ch')
const receiverName=computed(()=>windows.value?'CABLE Output':'BlackHole 2ch')
const blackhole=computed(()=>devices.value.find(d=>!['default','communications'].includes(d.deviceId)&&(windows.value?/(?:^CABLE(?:-[A-D])? Input\b|(?:扬声器|Speakers).*VB-Audio Virtual Cable)/i.test(d.label):/blackhole.*2ch/i.test(d.label))))
const inputName=computed(()=>({stopped:'接收器未开启',listening:'接收器已就绪',connecting:'本机工具连接中',connected:'本机工具已连接',error:'连接异常'})[input.value?.status||'stopped'])
async function refresh(){try{devices.value=(await navigator.mediaDevices.enumerateDevices()).filter(d=>d.kind==='audiooutput')}catch{/* Chinese fallback is shown by no-device state. */}}
async function info(){const r=await props.execute({type:'input-info'});if(r?.ok&&r.data)input.value=r.data as LiveInputInfo}
async function inputAction(type:'input-start'|'input-stop'|'input-rotate-token'|'input-test'){if(type==='input-start')await save();await props.execute({type});await info()}
async function save(){await props.execute({type:'set-config',config:JSON.parse(JSON.stringify(edit))},'直播连接设置已保存')}
async function toggleMonitor(){const config=JSON.parse(JSON.stringify(props.state.config));config.audio.monitorEnabled=!config.audio.monitorEnabled;const result=await props.execute({type:'set-config',config},config.audio.monitorEnabled?'本地监听已打开':'本地监听已关闭，直播输出继续');if(result?.ok)edit.audio.monitorEnabled=config.audio.monitorEnabled}
async function selectBlackHole(){if(!blackhole.value)return;edit.audio.streamDeviceId=blackhole.value.deviceId;edit.audio.mode='live';await save()}
onMounted(async()=>{await refresh();await info();const r=await props.execute({type:'get-runtime-info'});if(r?.ok&&r.data)runtime.value=r.data as typeof runtime.value;timer=setInterval(info,4000)})
onUnmounted(()=>clearInterval(timer))
</script>
<template>
 <section class="card connection-summary"><div><span class="eyebrow">直播声音与日常工作分开</span><h2>{{runtime?.localTest?'当前是独立本地测试窗口':state.config.audio.mode==='live'?'专用直播输出':'本地排练模式'}}</h2><p class="muted small">{{state.config.audio.mode==='live'?'只有小店的配音和歌曲进入指定虚拟声卡；关闭监听不停止直播。':'本地测试不会把声音送入虚拟声卡。默认安静，打开监听后才在本机发声。'}}</p></div><div class="row"><button class="btn ghost" @click="execute({type:'open-local-test'})"><Icon name="flask" :size="16"/>打开独立测试</button><button :class="['btn',state.config.audio.monitorEnabled?'primary':'ghost']" @click="toggleMonitor"><Icon :name="state.config.audio.monitorEnabled?'speaker':'mute'" :size="16"/>{{state.config.audio.monitorEnabled?'关闭本地监听':'打开本地监听'}}</button></div></section>
 <BilibiliConnection :send="execute" :desktop="isDesktop" :local-test="runtime?.localTest !== false"/>
 <LiveInputFailover :execute="execute" :local-test="runtime?.localTest"/>
 <div class="grid two">
  <section class="card"><div class="card-head"><h2>专供直播伴侣的画面</h2><span class="tag mint">9:16 · 1080 × 1920</span></div><p class="muted small">独立窗口只显示小店画面；后台界面、工作桌面和其他应用不会进入画面。</p><button class="btn primary" @click="execute({type:'open-capture'})"><Icon name="external" :size="16"/>打开专用采集窗口</button><ol class="steps"><li><b>1</b>直播伴侣 → 添加素材 → 窗口。</li><li><b>2</b>选择「赛博肥鱼 · 抖音直播采集（9:16）」，按竖屏铺满。</li><li><b>3</b>声音设置：麦克风选 {{receiverName}}，系统扬声器采集静音。</li></ol><p class="muted small">后台可收进系统托盘 / 菜单栏继续营业。电脑仍需保持运行；本应用不会改变整台电脑的睡眠或默认声音设置。</p></section>
  <section class="card"><div class="card-head"><h2>直播音频输出</h2><button class="link" @click="refresh"><Icon name="refresh" :size="14"/>重新检测</button></div><label>运行模式<select v-model="edit.audio.mode" aria-label="直播音频运行模式"><option value="test">本地测试 · 不送入直播声卡</option><option value="live">直播 · 只送入专用声卡</option></select></label><label>直播专用输出设备<select v-model="edit.audio.streamDeviceId"><option value="">请选择虚拟声卡</option><option v-for="d in devices.filter(d=>d.deviceId!=='default'&&d.deviceId!=='communications')" :key="d.deviceId" :value="d.deviceId">{{d.label||'音频设备'}}</option></select></label><div class="notice" :class="{warning:!blackhole}">{{blackhole?'已检测到 '+virtualName+'，可用于小店独立输出。':'尚未检测到 '+virtualName+'。请安装'+(windows?' VB-CABLE Windows 驱动':' BlackHole macOS 驱动')+'，完成后重新检测。'}}</div><div class="row"><button v-if="blackhole" class="btn ghost" @click="selectBlackHole">选用 {{virtualName}}</button><button class="btn ghost" @click="execute({type:'open-audio-setup'})">安装 / 查看虚拟声卡</button></div><p v-if="windows" class="muted small">小店输出选 CABLE Input；直播伴侣麦克风选 CABLE Output。关闭伴侣的系统声音采集及重复监听，保留 Windows 默认扬声器。</p><div class="form-grid"><label>直播总音量<input v-model.number="edit.audio.streamGain" type="range" min="0" max="1" step="0.05"/></label><label>配音音量<input v-model.number="edit.audio.speechGain" type="range" min="0" max="1" step="0.05"/></label><label>歌曲音量<input v-model.number="edit.audio.musicGain" type="range" min="0" max="1" step="0.05"/></label><label>说话时歌曲保留音量<input v-model.number="edit.audio.ducking" type="range" min="0" max="1" step="0.05"/></label></div><p class="muted small">{{stream?'当前输出：'+stream.label:'直播模式必须指定设备。设备断开时停止输出，不会切回电脑扬声器。'}} 系统朗读仅用于本地测试；直播配音请选千问。</p></section>
  <section class="card"><div class="card-head"><h2>本地监听</h2><span :class="['tag',state.config.audio.monitorEnabled?'mint':'']">{{state.config.audio.monitorEnabled?'本地可听':'本地安静'}}</span></div><label>监听设备<select v-model="edit.audio.monitorDeviceId"><option value="">电脑默认输出 / 耳机</option><option v-for="d in devices.filter(d=>!['default','communications'].includes(d.deviceId)&&!/(?:blackhole|VB-Audio Virtual Cable|^CABLE(?:-[A-D])? Input)/i.test(d.label))" :key="d.deviceId" :value="d.deviceId">{{d.label||'音频设备'}}</option></select></label><label>监听音量<input v-model.number="edit.audio.monitorGain" type="range" min="0" max="1" step="0.05"/></label><label class="check"><input v-model="edit.audio.monitorEnabled" type="checkbox"/><span>在本机监听直播混音<small>配音、歌曲和说话压低背景音会一起听到；不要在直播伴侣重复开监听。</small></span></label><div class="notice">关闭监听只静音本项目的监听通道。你电脑上的音乐、会议和其他声音保持原样。</div><div class="row-end"><button class="btn primary" @click="save">保存音频与连接设置</button></div></section>
  <section class="card"><div class="card-head"><h2>互动数据连接</h2><span class="tag" :class="{mint:input?.status==='connected'}">{{inputName}}</span></div><p class="muted small">从支持本机转发的弹幕来源接入，弹幕、礼物、进场统一送进小店。窗口采集与互动数据是两条连接。</p><div class="form-grid"><label>本机接入端口<input v-model.number="edit.input.port" type="number" min="1024" max="65535"/></label><label>上游消息格式<select v-model="edit.input.upstreamFormat"><option value="normalized">小店标准事件</option><option value="douyin-barrage">DouyinBarrageGrab 格式</option></select></label></div><label>已有弹幕工具的本机 WebSocket 地址 · 可留空<input v-model="edit.input.upstreamUrl" placeholder="ws://127.0.0.1:8888"/></label><div class="row"><button class="btn primary" @click="inputAction('input-start')">连接互动来源</button><button class="btn ghost" @click="inputAction('input-stop')">断开</button><button class="btn ghost" @click="inputAction('input-test')">接入自检 · 不调用 AI</button></div><div v-if="input?.endpoint" class="input-endpoint"><label>本机接入地址<input :value="input.endpoint" readonly/></label><label>本机接入令牌<input :value="input.token" :type="showToken?'text':'password'" readonly/></label><div class="row"><button class="link" @click="showToken=!showToken">{{showToken?'隐藏令牌':'显示令牌'}}</button><button class="link" @click="execute({type:'input-copy'})">复制连接信息</button><button class="link muted" @click="inputAction('input-rotate-token')">重置令牌</button></div></div><p class="muted small">本机转发接收 {{input?.received||0}} 条（可能含重发或过滤，不是独立礼物件数）· 拒绝 {{input?.rejected||0}} 次 · {{input?.message||'尚未接入真实弹幕来源，当前可用排练模式。'}}</p></section>
 </div>
 <InputStatistics :statistics="state.inputStatistics"/>
 <section class="card"><div class="card-head"><h2>项目自己的运行目录</h2><span class="tag">不改其他应用配置</span></div><p class="data-path">{{runtime?.dataDirectory||'桌面应用中显示本机数据目录'}}</p><p class="muted small">聊天、歌曲、设置和缓存保存在本项目的数据目录。本地测试使用独立目录。密钥通过系统安全存储加密，虚拟声卡驱动由系统管理。</p></section>
</template>
